def-hyp[predicate](
    __list__(Type.annotation(@X, Set(P@Set.def.order.partial)), Type.annotation(@a, P@Set.def.order.partial)),
    Eq(a, Set.order.max(X, P@Set.def.order.partial)),
    Logic.and(
        Set.mem(a, X),
        Logic.forall-typed(@x, X, Logic.neg(Rl.apply($\lt$@Set.def.order.partial, a, x)))
    )
)
